from microbit import *
import random

while True:
    # Перевіряємо, чи було струшування
    if accelerometer.was_gesture("shake"):
        number = random.randint(1, 6)
        if number == 1:
            display.show(Image("00000:00000:00900:00000:00000"))
        elif number == 2:
            display.show(Image("09000:00000:00000:00000:00090"))
        elif number == 3:
            display.show(Image("09000:00000:00900:00000:00090"))
        elif number == 4:
            display.show(Image("09090:00000:00000:00000:09090"))
        elif number == 5:
            display.show(Image("09090:00000:00900:00000:09090"))
        else:
            display.show(Image("09090:00000:09090:00000:09090"))
    # Невелика пауза між перевірками жесту
    sleep(20)
